        private void TxtPickInputReceived_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Enter || e.KeyCode == Keys.Tab)
            {
                // Si acaba de leer un QR con múltiples números de serie.
                if (TxtPickInputReceived.Text.Trim().Length > 0 && TxtPickInputReceived.Text.Trim().Contains(";"))
                {
                    GetFromQR();
                }
                else
                {
                    string inputBernafon = TxtPickInputReceived.Text.Trim().ToUpper();

                    if (!string.IsNullOrEmpty(inputBernafon))
                    {

                        listItems.Add(inputBernafon);

                        ReloadDataGridViewReceived();

                    }
                }
                TxtPickInputReceived.Clear();

            }

            else if (e.KeyCode == Keys.C && e.Control)
            {
                Compare();
            }
        }

        private void BtnCompare_Click(object sender, EventArgs e)
        {
            Compare();
        }

        private void GetFromQR()
        {
            dataGridViewReceived.Rows.Clear();
            List<string> newSeries = TxtPickInputReceived.Text.Trim().Split(";").ToList();

            listItems.AddRange(newSeries);

            ReloadDataGridViewReceived();
        }

        private void ReloadDataGridViewReceived()
        {
            dataGridViewReceived.Rows.Clear();
            foreach (var item in listItems)
            {
                dataGridViewReceived.Rows.Add(1, item);
            }

            //dataGridViewReceived.DataSource = listItems.Select(x => new { UnitsReceivedInventory = 1, SerialReceivedInventory = x }).ToList();

        }

        private void BtnGenerateQr(object sender, EventArgs e)
        {
            Functions.GenerateQRBernafon(dataGridViewReceived);
        }

        private void CleanFrm()
        {
            dataGridViewReceived.Rows.Clear();
            TxtPickInputReceived.Clear();
        }

        private void reloadQuantityLabel()
        {
            // Elimino la fila por defecto
            int rowNumbers = dataGridView1.AllowUserToAddRows ? dataGridView1.Rows.Count - 1 : dataGridView1.Rows.Count;

            LblQty.Text = $"Audífonos Restantes: {rowNumbers}";
        }

        private void dataGridView1_DragDrop(object sender, DragEventArgs e)
        {
            string[] archivos;

            try
            {
                archivos = (string[])e.Data.GetData(DataFormats.FileDrop);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Ha ocurrido un error al leer la ruta del archivo: {ex}.", "Error de lectura de ruta", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            if (archivos.Length == 0)
            {
                MessageBox.Show("El archivo no pudo ser capturado correctamente.", "Error de captura de archivo", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            //CleanFrm();
            dataGridView1.Rows.Clear();
            int line = 0;

            foreach (string ruta in archivos)
            {
                string ext = Path.GetExtension(ruta).ToLower();
                if (ext != ".xls" && ext != ".xlsx")
                {
                    MessageBox.Show($"El formato del archivo {ext} no es válido. Solo le permiten archivos .xsl o .xlsx", "Archivo incorrecto", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }

                Headers header = new Headers();
                header.ArtCode.Name = AppSettings.settings.InventoryAB.ColumnCode;
                header.Qty.Name = AppSettings.settings.InventoryAB.ColumnUnits;
                header.Description.Name = AppSettings.settings.InventoryAB.ColumnDescription;
                header.SerialNr.Name = AppSettings.settings.InventoryAB.ColumnSerialNumber;
                header.DueDate.Name = AppSettings.settings.InventoryAB.ColumnDueDate;

                try
                {
                    var lista = Functions.ReadAnexoFile(ruta, header, header.ArtCode.Name);
                    foreach (var item in lista)
                    {
                        if (cbNoahLink.Checked)
                        {
                            if (!item.Description.ToLower().Contains("noah"))
                            {
                                continue;
                            }
                        }
                        else
                        {
                            if (string.IsNullOrEmpty(item.SerialNumber))
                            {
                                continue;
                            }
                        }

                        //if (line == 10)
                        //{
                        //    break;
                        //}

                        dataGridView1.Rows.Add();
                        dataGridView1.Rows[line].Cells["QuantityItem"].Value = item.Quantity;
                        dataGridView1.Rows[line].Cells["CodItem"].Value = item.CodItem;
                        dataGridView1.Rows[line].Cells["DescriptionItem"].Value = item.Description;
                        dataGridView1.Rows[line].Cells["SerialNumber"].Value = item.SerialNumber;
                        dataGridView1.Rows[line].Cells["DueDate"].Value = item.DueDate;
                        line++;

                        itemAnexos.Add(item);
                    }

                    reloadQuantityLabel();

                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Hubo un error al obtener los datos del archivo: {ex}", "Archivo incorrecto", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }

            }
        }

        private void dataGridView1_DragEnter(object sender, DragEventArgs e)
        {
            if (e.Data.GetDataPresent(DataFormats.FileDrop))
            {
                e.Effect = DragDropEffects.Copy; // Muestra el cursor de copiar
            }
            else
            {
                e.Effect = DragDropEffects.None;
            }
        }


        private void BtnCleanAnexo_Click(object sender, EventArgs e)
        {
            dataGridView1.Rows.Clear();
            loteCompared = false;
            reloadQuantityLabel();
        }

        private void dataGridView1_UserDeletedRow(object sender, DataGridViewRowEventArgs e)
        {
            reloadQuantityLabel();
        }

        private void BtnCleanReceived_Click(object sender, EventArgs e)
        {
            listItems.Clear();
            dataGridViewReceived.Rows.Clear();
            TxtPickInputReceived.Clear();
            loteCompared = false;
        }


        private void Compare()
        {
            try
            {
                int quantityRows = dataGridViewReceived.Rows.Count; // Para restar y saber si quedaron restantes
                if (quantityRows == 0)
                {
                    MessageBox.Show("No se han cargado filas en al pestaña 'Físicos'.", "Tabla vacía", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                List<string?> serialNumbers = new List<string?>();

                if (cbNoahLink.Checked)
                {
                    serialNumbers = dataGridView1.Rows
                                                .Cast<DataGridViewRow>()
                                                .Where(r => !r.IsNewRow && r.Cells["CodItem"].Value != null)
                                                .Select(r => r.Cells["CodItem"].Value.ToString()).ToList();
                }
                else
                {
                    serialNumbers = dataGridView1.Rows
                                                .Cast<DataGridViewRow>()
                                                .Where(r => !r.IsNewRow && r.Cells["SerialNumber"].Value != null)
                                                .Select(r => r.Cells["SerialNumber"].Value.ToString()).ToList();
                }

                HashSet<string?> stockEsperado = new HashSet<string?>(serialNumbers);

                // Evito contabilizar las filas vacías
                if (stockEsperado.Count == 0)
                {
                    MessageBox.Show("No se han cargado filas en al pestaña 'Anexo'.", "Tabla vacía", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }


                foreach (DataGridViewRow row in dataGridViewReceived.Rows)
                {
                    if (row.IsNewRow) continue;

                    if (loteCompared == true && row.Tag != null && row.Tag == "1")
                    {
                        quantityRows--;
                        continue; // Si loteCompared es true voy a comparar solo las filas que antes tuvieron un error
                    }

                    string? serie = row.Cells["SerialReceivedInventory"].Value?.ToString();

                    if (string.IsNullOrEmpty(serie)) continue;

                    string serieSubString = serie.Substring(2);

                    if (stockEsperado.Contains(serie) || stockEsperado.Contains(serieSubString))
                    {
                        // Coincide → eliminar del grid1
                        EliminarFilaDgv(dataGridView1, serie);
                        row.DefaultCellStyle.BackColor = Color.White;
                        row.Tag = "1";  // Identifico que ya fue matcheado correctamente
                        quantityRows--;
                    }
                    else
                    {

                        // No coincide → marcar en rojo
                        row.DefaultCellStyle.BackColor = Color.Red;
                        row.Tag = "0";  // Identifico que no se encontró un ítem del anexo para matchear
                    }
                }


                reloadQuantityLabel();

                if (quantityRows != 0)
                {
                    MessageBox.Show("Algunos artículos no se han encontrado en el Anexo.", "Diferencias de stock", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                }
                else
                {
                    MessageBox.Show("Todos los artículos están correctos.", "Stock correcto", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }

                loteCompared = true; // Ya fue comparado, con o sin errores

            }
            catch (Exception)
            {

                throw;
            }
        }

        private void EliminarFilaDgv(DataGridView dgv, string serie)
        {

            DataGridViewRow? rowDelete = new DataGridViewRow();

            if (cbNoahLink.Checked)
            {
                rowDelete = dgv.Rows.Cast<DataGridViewRow>().FirstOrDefault(row => row.Cells["CodItem"].Value?.ToString() == serie);
            }
            else
            {
                rowDelete = dgv.Rows.Cast<DataGridViewRow>().FirstOrDefault(row => row.Cells["SerialNumber"].Value?.ToString() == serie);
            }

            if (rowDelete != null)
            {
                dgv.Rows.Remove(rowDelete);
            }
        }

        private void BtnTests_Click(object sender, EventArgs e)
        {
            dataGridViewReceived.Rows.Clear();
            loteCompared = false;

            aux += 30;
            for (int i = aux - 30; i < aux && aux <= limite; i++)
            {
                string value = listItems[i];
                if (value.Contains("/"))
                {
                    value = value.Split("/")[0];
                }
                dataGridViewReceived.Rows.Add(1, value);
            }

            if (aux >= limite)
            {
                MessageBox.Show("Ya está máquina.");
            }
        }

