        private void BtnPasteAnexo_Click(object sender, EventArgs e)
        {
            string clipboardText = Clipboard.GetText();

            Headers header = new Headers();
            header.ArtCode.Name = AppSettings.settings.IngresoBernafon.ColumnCode.ToString();
            header.Qty.Name = AppSettings.settings.IngresoBernafon.ColumnUnits.ToString();
            header.Description.Name = AppSettings.settings.IngresoBernafon.ColumnDescription.ToString();
            header.SerialNr.Name = AppSettings.settings.IngresoBernafon.ColumnSerialNumber.ToString();
            header.DueDate.Name = AppSettings.settings.IngresoBernafon.ColumnDueDate.ToString();

            List<ItemAnexo>? itemsAnexo = Functions.ReadAnexo(clipboardText, header);

            if (itemsAnexo == null)
            {
                return;
            }

            if (itemsAnexo.Count == 0)
            {
                return;
            }

            foreach (var item in itemsAnexo)
            {
                dataGridView1.Rows.Add(
                    item.Quantity.ToString(),
                    item.CodItem,
                    item.Description,
                    item.SerialNumber,
                    item.DueDate
                );
            }
        }
    }
